	&lt;li style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Segoe UI Symbol&amp;quot;,sans-serif&quot;&gt;⁠&lt;/span&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Yapamayacakları işlerin teklif edilmesinin &amp;ouml;n&amp;uuml;ne ge&amp;ccedil;eceğiz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
